passes.fragment:
precision highp float;
// Provided by the engine for every shader.
uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform vec2 iMouseVel;
uniform vec3 u_clickData[24];
uniform sampler2D iChannel0;
uniform sampler2D iChannel1;
uniform sampler2D iChannel2;
uniform sampler2D iChannel3;

// One uniform per control in the schema, named u_<key>.
uniform float u_speed_rate;
uniform bool u_glow;
uniform vec3 u_tint;
uniform float u_mode;
uniform float u_speedRate;

varying vec2 vUv;

float commonValue() { return 1.0; }
void main() { gl_FragColor = texture2D(iChannel0, vUv) * u_speed_rate; }

#extension GL_OES_standard_derivatives : enable
precision highp float;
// Provided by the engine for every shader.
uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform vec2 iMouseVel;
uniform vec3 u_clickData[24];
uniform sampler2D iChannel0;
uniform sampler2D iChannel1;
uniform sampler2D iChannel2;
uniform sampler2D iChannel3;

// One uniform per control in the schema, named u_<key>.
uniform float u_speed_rate;
uniform bool u_glow;
uniform vec3 u_tint;
uniform float u_mode;
uniform float u_speedRate;

varying vec2 vUv;

float commonValue() { return 1.0; }
vec4 tint() { return vec4(commonValue()); }
void main() { float edge = fwidth(vUv.x); gl_FragColor = texture2D(iChannel0, vUv) * tint() * edge; }
